const statusLabels: Record<string, string> = { draft: 'مسودة', ready_for_review: 'جاهز للمراجعة', in_review: 'قيد المراجعة', changes_requested: 'تعديلات مطلوبة', approved: 'معتمد', archived: 'مؤرشف', enabled: 'مفعل', disabled: 'معطل', PAUSED: 'متوقف مؤقتاً', LOBBY: 'ردهة', CLOSED: 'مغلق', QUESTION_READING: 'قراءة السؤال', QUESTION_FAILED: 'تعذر السؤال', MATCH_COMPLETE: 'انتهت المباراة', staged: 'وضع مرحلي', configured: 'مهيأ', reachable: 'متاح', enforced: 'مفروضة', emulator_disabled: 'غير مفروضة محلياً', blocked: 'محجوب', completed: 'مكتمل', classic: 'تقليدي', image: 'صورة', video: 'فيديو', charades: 'تمثيل' };
const inventoryLabels: Record<string, { label: string; definition: string }> = { adminQuestionDrafts: { label: 'مسودات الأسئلة', definition: 'سجلات عمل داخلية، وليست أسئلة منشورة.' }, adminReviewRequests: { label: 'طلبات المراجعة', definition: 'طلبات مرتبطة بمسودات ضمن نطاقك.' }, adminRoomSummaries: { label: 'ملخصات الغرف', definition: 'ملخصات تشغيلية مختصرة للغرف.' }, adminOperations: { label: 'عمليات الإدارة', definition: 'عمليات موثقة قابلة للتدقيق.' } };
