function stateCopy(state: string) { return ({ loading: 'جارٍ التحقق من صلاحيتك…', forbidden: 'لا تملك صلاحية الوصول إلى الاستوديو الإداري.', unavailable: 'خدمات الإدارة غير متاحة في هذه البيئة.', error: 'تعذر تحديث صلاحية الإدارة. حدّث الصفحة بعد إعادة تسجيل الدخول.' } as Record<string, string>)[state]; }
function labelStatus(value: unknown) { const raw = String(value ?? '—'); return statusLabels[raw] ?? raw; }
function text(value: unknown) { return typeof value === 'string' && value.trim() ? value : typeof value === 'number' && Number.isFinite(value) ? String(value) : '—'; }
function isConflict(error: unknown) { const code = (error as { code?: unknown })?.code; return typeof code === 'string' && (code === 'aborted' || code.endsWith('/aborted')); }
function asDate(value: unknown) { const seconds = value && typeof value === 'object' && 'seconds' in value ? Number((value as { seconds: unknown }).seconds) : Number.NaN; if (Number.isFinite(seconds)) return new Intl.DateTimeFormat('ar-KW', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(seconds * 1000)); return typeof value === 'string' ? value : '—'; }
function capabilities(session: AdminSession | null, capability: AdminCapability) { return Boolean(session?.capabilities.includes(capability)); }
function useAdmin() { return useOutletContext<AdminOutlet | null>(); }

export function AdminShell() {
  const auth = useFirebaseAuth(); const location = useLocation(); const [session, setSession] = useState<AdminSession | null>(null); const [state, setState] = useState('loading'); const [dirty, setDirty] = useState(false); const [navOpen, setNavOpen] = useState(false); const dirtyGuard = useRef<string | null>(null); const navToggle = useRef<HTMLButtonElement>(null);
  useEffect(() => { let active = true; if (auth.status === 'loading') return; if (auth.status !== 'google' && auth.status !== 'password') { setState(auth.status === 'unavailable' ? 'unavailable' : 'forbidden'); return; } void getAdminSession().then(value => { if (active) { setSession(value); setState('ready'); } }).catch(error => { if (active) setState(String(error?.code || '').includes('permission') ? 'forbidden' : 'error'); }); return () => { active = false; }; }, [auth.status]);
  useEffect(() => { if (!dirty) return; const token = crypto.randomUUID(); dirtyGuard.current = token; window.history.pushState({ ...(window.history.state ?? {}), adminDirtyGuard: token }, '', `${location.pathname}${location.search}${location.hash}`); let restoring = false; let leaving = false; const onPopState = () => { if (dirtyGuard.current !== token) return; if (restoring) { restoring = false; return; } if (leaving) return; if (window.confirm('لديك تعديلات غير محفوظة. هل تريد مغادرة المحرر؟')) { leaving = true; setDirty(false); window.history.back(); } else { restoring = true; window.history.forward(); } }; window.addEventListener('popstate', onPopState); return () => window.removeEventListener('popstate', onPopState); }, [dirty, location.hash, location.pathname, location.search]);
  const discardDirty = (afterDiscard?: () => void) => { const token = dirtyGuard.current; const currentToken = (window.history.state as { adminDirtyGuard?: string } | null)?.adminDirtyGuard; setDirty(false); if (!token || currentToken !== token) { afterDiscard?.(); return; } dirtyGuard.current = null; window.setTimeout(() => { const finish = () => { window.removeEventListener('popstate', finish); window.setTimeout(() => afterDiscard?.(), 0); }; window.addEventListener('popstate', finish); window.history.back(); }, 0); };
  const confirmNavigation = (event: React.MouseEvent<HTMLAnchorElement>) => { if (dirty) { if (!window.confirm('لديك تعديلات غير محفوظة. هل تريد مغادرة المحرر؟')) { event.preventDefault(); return; } setDirty(false); } setNavOpen(false); };
  useEffect(() => { if (!navOpen) return; const onKeyDown = (event: KeyboardEvent) => { if (event.key !== 'Escape') return; event.preventDefault(); setNavOpen(false); window.setTimeout(() => navToggle.current?.focus(), 0); }; window.addEventListener('keydown', onKeyDown); return () => window.removeEventListener('keydown', onKeyDown); }, [navOpen]);
  if (state !== 'ready' || !session) return <main className="admin-page spatial-admin spatial-admin--state" id="main-content"><InternalHeader /><section className="admin-state" role={state === 'loading' ? 'status' : 'alert'}><p className="eyebrow">استوديو الإدارة</p><h1>{stateCopy(state)}</h1>{state === 'forbidden' ? <Link className="button button--primary" to="/login">تسجيل الدخول بحساب موثّق</Link> : null}<Link className="text-link" to="/">العودة إلى الرئيسية</Link></section></main>;
  return <main className="admin-page spatial-admin" id="main-content"><header className="admin-topbar"><Link aria-label="الخلية" className="wordmark" to="/" onClick={confirmNavigation}><BrandMark /></Link><span>إدارة · {session.mutationMode === 'staged' ? 'وضع مرحلي' : 'وضع تشغيلي'}</span><span>مسودات تصحيح الفئات · {session.categoryCorrectionDraftMode === 'enabled' ? 'متاحة' : 'مرحلية'}</span><span className="admin-identity">جلسة {auth.status === 'password' ? 'بريد/كلمة مرور' : 'Google'} موثقة</span><ThemeToggle compact /></header><div className="admin-layout"><button type="button" className="admin-nav-toggle" aria-expanded={navOpen} aria-controls="admin-navigation" onClick={() => setNavOpen(open => !open)} ref={navToggle}>أقسام الإدارة</button><nav id="admin-navigation" className={`admin-nav ${navOpen ? 'is-open' : ''}`} aria-label="تنقل الإدارة">{links.filter(link => capabilities(session, link.capability)).map(link => <Link key={link.to} className={location.pathname.startsWith(link.to) ? 'is-current' : ''} to={link.to} onClick={confirmNavigation}>{link.label}</Link>)}</nav><section className="admin-workspace"><Outlet context={{ session, dirty, setDirty, discardDirty } satisfies AdminOutlet} /></section></div></main>;
}

export function AdminOverviewRoute() {
  const [overview, setOverview] = useState<{ inventory: Record<string, number>; mutationMode: string; published?: { releaseId: string | null; questionCount: number | null; categoryCount: number | null; scoped: boolean } } | null>(null); const [error, setError] = useState(false);
  const reload = () => { setError(false); void getAdminOverview().then(setOverview).catch(() => setError(true)); };
  useEffect(reload, []);
  return <AdminSurface title="النظرة العامة" description="يفصل هذا الملخص بين الإصدار المنشور الثابت وسجلات التأليف التشغيلية ضمن نطاق جلستك.">{error ? <Recovery message="تعذر تحميل الملخص؛ لم تُعرض أصفار بديلة." retry={reload} /> : !overview ? <LoadingRows /> : <><section className="admin-overview-group" aria-labelledby="published-inventory"><div><p className="eyebrow">المحتوى المباشر</p><h2 id="published-inventory">الإصدار المنشور</h2></div>{overview.published?.releaseId ? <dl className="admin-inventory"><div><dt>أسئلة منشورة<small>{overview.published.scoped ? 'عدد ضمن نطاق الفئات المصرّح به.' : 'عدد الإصدار النشط كاملاً.'}</small></dt><dd>{text(overview.published.questionCount)}</dd></div><div><dt>فئات الإصدار<small>تشمل الفئات المعلّقة وغير القابلة للعب؛ لا تخفيها لوحة الإدارة.</small></dt><dd>{text(overview.published.categoryCount)}</dd></div><div><dt>معرف الإصدار النشط</dt><dd><bdi dir="ltr">{overview.published.releaseId}</bdi></dd></div></dl> : <p className="admin-notice">لا يوجد إصدار منشور قابل للقراءة ضمن صلاحيتك الحالية.</p>}</section><section className="admin-overview-group" aria-labelledby="draft-inventory"><div><p className="eyebrow">التأليف والمراجعة</p><h2 id="draft-inventory">السجلات الإدارية</h2></div><dl className="admin-inventory">{Object.entries(overview.inventory).map(([key, count]) => { const item = inventoryLabels[key] ?? { label: 'سجل إداري', definition: 'عدد مرئي ضمن نطاقك.' }; return <div key={key}><dt>{item.label}<small>{item.definition}</small></dt><dd>{count}</dd></div>; })}</dl></section><p className="admin-notice">النشر والتوقيع لا يُنفّذان من المتصفح. ظهور الإصدار هنا لا يمنح صلاحية تغيير مؤشر الإصدار أو بياناته الثابتة.</p></>}</AdminSurface>;
}

function publishedReadiness(value: unknown) { const item = value && typeof value === 'object' ? value as Row : {}; const names = [{ key: 'huroof', label: 'الحروف' }, { key: 'categories', label: 'الفئات' }, { key: 'charades', label: 'تمثيل' }]; return <span className="admin-readiness">{names.map(({ key, label }) => <Status key={key} value={item[key] === true ? 'enabled' : 'disabled'}>{label}</Status>)}</span>; }
function publishedQuestionsPath(categoryId?: unknown, releaseId?: unknown) { const params = new URLSearchParams(); if (typeof categoryId === 'string' && categoryId) params.set('categoryId', categoryId); if (typeof releaseId === 'string' && releaseId) params.set('releaseId', releaseId); const query = params.toString(); return `/admin/questions${query ? `?${query}` : ''}`; }
function publishedQuestionPath(questionId: string, releaseId: string) { return `/admin/questions/${encodeURIComponent(questionId)}?releaseId=${encodeURIComponent(releaseId)}`; }
function publishedCategoryTopic(value: Row) { const id = typeof value.id === 'string' ? value.id : ''; const displayNameAr = typeof value.labelAr === 'string' ? value.labelAr : ''; if (!id || !displayNameAr) return null; const topicId = categoryTopicIdForCategory({ id, displayNameAr }); return categoryTopics.find(topic => topic.id === topicId)?.labelAr ?? null; }

export function AdminPublishedQuestionsRoute() {
  const { id } = useParams(); const [searchParams, setSearchParams] = useSearchParams(); const requestId = useRef(0); const [items, setItems] = useState<Row[]>([]); const [detail, setDetail] = useState<Row | null>(null); const [state, setState] = useState<'loading' | 'ready' | 'error'>('loading'); const [nextCursor, setNextCursor] = useState<string | null>(null); const [releaseId, setReleaseId] = useState<string | undefined>(); const [categories, setCategories] = useState<Row[]>([]); const [categoryError, setCategoryError] = useState(false); const categoryId = searchParams.get('categoryId') ?? ''; const modality = searchParams.get('modality') ?? ''; const requestedReleaseId = searchParams.get('releaseId') ?? undefined; const requestedTopicId = searchParams.get('topicId') ?? '';
  const categoryTopicId = (category: Row) => categoryTopicIdForCategory({ id: String(category.id), displayNameAr: String(category.labelAr ?? '') });
  const selectedCategory = categories.find(category => String(category.id) === categoryId);
  const topicId = categoryTopics.some(topic => topic.id === requestedTopicId) ? requestedTopicId : selectedCategory ? categoryTopicId(selectedCategory) : '';
  const visibleCategories = topicId ? categories.filter(category => categoryTopicId(category) === topicId) : categories;
  const chooseTopic = (value: string) => { const next = new URLSearchParams(searchParams); if (value) next.set('topicId', value); else next.delete('topicId'); next.delete('categoryId'); setSearchParams(next); };
  const setFilter = (name: 'categoryId' | 'modality', value: string) => { const next = new URLSearchParams(searchParams); if (value) next.set(name, value); else next.delete(name); setSearchParams(next); };
  const load = async (append = false) => { const token = ++requestId.current; setState('loading'); if (!append) { setItems([]); setNextCursor(null); } try { if (id) { const value = await getPublishedQuestion(id, requestedReleaseId); if (token !== requestId.current) return; setDetail(value); setReleaseId(value.releaseId); setItems([]); setNextCursor(null); } else { const page = await listPublishedQuestions({ limit: 50, ...(append && nextCursor && releaseId ? { cursor: nextCursor, releaseId } : requestedReleaseId ? { releaseId: requestedReleaseId } : {}), ...(categoryId ? { categoryId } : {}), ...(modality ? { modality } : {}) }); if (token !== requestId.current) return; setReleaseId(page.releaseId); setItems(current => append ? [...current, ...page.items] : page.items); setNextCursor(page.nextCursor); } setState('ready'); } catch { if (token === requestId.current) setState('error'); } };
  useEffect(() => { let live = true; void (async () => { const all: Row[] = []; let cursor: string | null = null; let bound: string | undefined; try { do { const page = await listPublishedCategories({ limit: 100, ...(cursor && bound ? { cursor, releaseId: bound } : requestedReleaseId ? { releaseId: requestedReleaseId } : {}) }); bound = page.releaseId; all.push(...page.items); cursor = page.nextCursor; } while (cursor); if (live) { setCategories(all); setCategoryError(false); } } catch { if (live) { setCategories([]); setCategoryError(true); } } })(); return () => { live = false; }; }, [requestedReleaseId]);
  useEffect(() => { setReleaseId(requestedReleaseId); setNextCursor(null); if (!id && topicId && !categoryId) { ++requestId.current; setItems([]); setState('ready'); return; } void load(false); }, [id, categoryId, modality, requestedReleaseId, topicId]);
  if (id) return <AdminSurface title="تفاصيل سؤال منشور" description="قراءة من الإصدار المنشور الثابت. لا يمكن تحرير هذا السجل من لوحة الإدارة." hideDefaultHeader={state === 'ready' && Boolean(detail)}>{state === 'loading' ? <LoadingRows /> : state === 'error' ? <Recovery message="تعذر تحميل السؤال المنشور أو تغيّر الإصدار النشط." retry={() => void load(false)} /> : detail ? <PublishedQuestionInspectionDetail value={detail} /> : null}</AdminSurface>;
  const categoryLabels = Object.fromEntries(categories.map(category => [String(category.id), text(category.labelAr)]));
  return <AdminSurface title="بنك الأسئلة المنشور" description="سجلات الإصدار المنشور فقط؛ التأليف يظهر في قسم المسودات المنفصل. اختر الموضوع ثم الفئة لتصفية الأسئلة المنشورة."><div className="admin-toolbar admin-toolbar--published"><label>الموضوع<select aria-label="موضوع الفئة المنشورة" value={topicId} onChange={event => chooseTopic(event.target.value)} disabled={categoryError || !categories.length}><option value="">كل الموضوعات</option>{categoryTopics.filter(topic => categories.some(category => categoryTopicId(category) === topic.id)).map(topic => <option key={topic.id} value={topic.id}>{topic.labelAr}</option>)}</select></label><label>الفئة<select aria-label="فئة منشورة" value={categoryId} onChange={event => setFilter('categoryId', event.target.value)} disabled={state === 'loading' || categoryError || !categories.length}><option value="">{topicId ? 'اختر الفئة' : 'كل الفئات المتاحة'}</option>{visibleCategories.map(category => <option key={String(category.id)} value={String(category.id)}>{text(category.labelAr)}</option>)}</select></label><label>نمط السؤال<select aria-label="نمط منشور" value={modality} onChange={event => setFilter('modality', event.target.value)} disabled={state === 'loading'}><option value="">كل الأنماط</option>{['classic', 'image', 'video', 'charades'].map(value => <option key={value} value={value}>{labelStatus(value)}</option>)}</select></label><button className="button button--secondary" type="button" onClick={() => { const next = new URLSearchParams(searchParams); next.delete('topicId'); next.delete('categoryId'); next.delete('modality'); setSearchParams(next); }} disabled={!topicId && !categoryId && !modality}>مسح المرشحات</button><button className="button button--secondary" type="button" onClick={() => void load(false)} disabled={state === 'loading' || Boolean(topicId && !categoryId)}>تحديث</button></div>{categoryError ? <p className="admin-notice" role="alert">تعذر تحميل قائمة الفئات كاملة؛ أعد المحاولة قبل استخدام مرشح الفئة.</p> : null}{topicId && !categoryId ? <p className="admin-empty">اختر فئة من موضوع {categoryTopics.find(topic => topic.id === topicId)?.labelAr} لعرض أسئلتها.</p> : state === 'loading' ? <LoadingRows /> : state === 'error' ? <Recovery message="تعذر تحميل بنك الإصدار. أعد المحاولة للتحقق من الإصدار الحالي." retry={() => void load(false)} /> : items.length ? <div className="admin-table-wrap"><div className="admin-table admin-table--published" role="table" aria-label="بنك الأسئلة المنشور"><div className="admin-table__row admin-table__row--head" role="row"><b role="columnheader">السؤال</b><b role="columnheader">الفئة</b><b role="columnheader">النمط</b><b role="columnheader">الإجراء</b></div>{items.map(item => <div className="admin-table__row" role="row" key={String(item.id)}><span data-label="السؤال" role="cell"><small>{text(item.headerAr)}</small><b className="admin-question-prompt">{text(item.promptAr)}</b></span><span data-label="الفئة" role="cell">{categoryLabels[String(item.categoryId)] ?? 'فئة غير معروضة'}<small><bdi dir="ltr">{text(item.categoryId)}</bdi></small></span><span data-label="النمط" role="cell"><Status value={item.modality} /></span><span data-label="الإجراء" role="cell"><Link className="text-link" to={`/admin/questions/${encodeURIComponent(String(item.id))}${releaseId ? `?releaseId=${encodeURIComponent(releaseId)}` : ''}`}>عرض السؤال</Link></span></div>)}</div></div> : <p className="admin-empty">{categoryId ? 'لا توجد أسئلة منشورة ضمن هذه الفئة في الإصدار أو نطاقك.' : 'لا توجد أسئلة منشورة مطابقة للمرشحات أو ضمن نطاقك.'}</p>}{nextCursor ? <button className="button button--secondary" type="button" onClick={() => void load(true)} disabled={state === 'loading'}>تحميل الصفحة التالية</button> : null}<p className="admin-hint">الإصدار: <bdi dir="ltr">{releaseId ?? 'جارٍ التحقق'}</bdi></p></AdminSurface>;
}

export function AdminPublishedCategoriesRoute() {
  const admin = useAdmin(); const navigate = useNavigate(); const { id } = useParams(); const [searchParams] = useSearchParams(); const requestId = useRef(0); const routeIdentity = useRef<{ categoryId?: string; releaseId?: string }>({}); const loadedIdentity = useRef<{ categoryId: string; releaseId: string } | null>(null); const [items, setItems] = useState<Row[]>([]); const [detail, setDetail] = useState<Row | null>(null); const [correction, setCorrection] = useState<Row | null>(null); const [proposedLabelAr, setProposedLabelAr] = useState(''); const [internalNote, setInternalNote] = useState(''); const [saveState, setSaveState] = useState<'idle' | 'saving'>('idle'); const [saveMessage, setSaveMessage] = useState(''); const [state, setState] = useState<'loading' | 'ready' | 'error'>('loading'); const [nextCursor, setNextCursor] = useState<string | null>(null); const [releaseId, setReleaseId] = useState<string | undefined>(); const requestedReleaseId = searchParams.get('releaseId') ?? undefined;
  const categoryPath = (categoryId: string, release?: string) => `/admin/categories/${encodeURIComponent(categoryId)}${release ? `?releaseId=${encodeURIComponent(release)}` : ''}`;
  const isCurrentIdentity = (categoryId: string, release: string) => routeIdentity.current.categoryId === categoryId && (routeIdentity.current.releaseId === undefined || routeIdentity.current.releaseId === release);
  const load = async (append = false) => { const token = ++requestId.current; setState('loading'); try { if (id) { const value = await getPublishedCategory(id, requestedReleaseId); if (token !== requestId.current) return; const draft = await getCategoryCorrection(id, value.releaseId); if (token !== requestId.current) return; loadedIdentity.current = { categoryId: id, releaseId: value.releaseId }; routeIdentity.current = { categoryId: id, releaseId: value.releaseId }; setDetail(value); setCorrection(draft as unknown as Row); setProposedLabelAr(draft.draft?.proposedLabelAr ?? value.labelAr); setInternalNote(draft.draft?.internalNote ?? ''); setSaveMessage(''); setReleaseId(value.releaseId); } else { const page = await listPublishedCategories({ limit: 50, ...(append && nextCursor && releaseId ? { cursor: nextCursor, releaseId } : requestedReleaseId ? { releaseId: requestedReleaseId } : {}) }); if (token !== requestId.current) return; setReleaseId(page.releaseId); setItems(current => append ? [...current, ...page.items] : page.items); setNextCursor(page.nextCursor); } setState('ready'); } catch { if (token === requestId.current) setState('error'); } };
  const beginRouteLoad = () => { routeIdentity.current = { categoryId: id, releaseId: requestedReleaseId }; loadedIdentity.current = null; setReleaseId(requestedReleaseId); setNextCursor(null); setCorrection(null); setSaveState('idle'); void load(false); };
  useEffect(() => { const prior = loadedIdentity.current; const changedRecord = Boolean(id && prior && (prior.categoryId !== id || (requestedReleaseId !== undefined && prior.releaseId !== requestedReleaseId))); if (changedRecord && admin?.dirty) { if (!window.confirm('لديك مسودة تصحيح غير محفوظة. هل تريد مغادرة الفئة؟')) { navigate(categoryPath(prior!.categoryId, prior!.releaseId), { replace: true }); return; } admin.discardDirty(beginRouteLoad); return; } if (prior && id === prior.categoryId && (requestedReleaseId === undefined || requestedReleaseId === prior.releaseId) && admin?.dirty) return; beginRouteLoad(); }, [id, requestedReleaseId]);
  const correctionDraft = correction?.draft && typeof correction.draft === 'object' ? correction.draft as Row : null;
  const canEditCorrection = correction?.canEdit === true && correction?.correctionDraftMode === 'enabled' && capabilities(admin?.session ?? null, 'categories.write');
  const correctionGateStaged = correction?.correctionDraftMode === 'staged' || admin?.session.categoryCorrectionDraftMode === 'staged';
  const saveCorrection = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!id || !detail || typeof detail.releaseId !== 'string' || !canEditCorrection || saveState === 'saving') return; const submittedCategoryId = id; const submittedReleaseId = detail.releaseId; setSaveState('saving'); setSaveMessage('جارٍ حفظ مسودة التصحيح…'); try { const result = await saveCategoryCorrection({ categoryId: submittedCategoryId, releaseId: submittedReleaseId, operationId: crypto.randomUUID(), expectedRevision: Number(correctionDraft?.revision ?? 0), draft: { proposedLabelAr, internalNote } }); if (!isCurrentIdentity(submittedCategoryId, submittedReleaseId)) return; setCorrection(current => current ? { ...current, draft: { ...((current.draft as Row) ?? {}), categoryId: submittedCategoryId, proposedLabelAr, internalNote, status: 'draft', revision: result.revision } } : current); admin?.setDirty(false); setSaveMessage('حُفظت مسودة التصحيح. لا يتغير الإصدار المنشور أو اللاعبون بهذا الحفظ.'); } catch (error) { if (!isCurrentIdentity(submittedCategoryId, submittedReleaseId)) return; setSaveMessage(isConflict(error) ? 'تعارض في المسودة: بقي نصك كما هو. حدّث الفئة قبل محاولة الحفظ مرة أخرى.' : 'تعذر حفظ مسودة التصحيح؛ بقي النص في النموذج.'); } finally { if (isCurrentIdentity(submittedCategoryId, submittedReleaseId)) setSaveState('idle'); } };
  const protectQuestionNavigation = (event: React.MouseEvent<HTMLAnchorElement>, target: string) => { if (!admin?.dirty) return; event.preventDefault(); if (!window.confirm('لديك مسودة تصحيح غير محفوظة. هل تريد مغادرة الفئة؟')) return; admin.discardDirty(() => navigate(target)); };
  if (id) return <AdminSurface title="تفاصيل فئة منشورة" description="هذه قراءة من فهرس الإصدار الثابت، مع عدد الأسئلة وحالة جاهزية اللعب.">{state === 'loading' ? <LoadingRows /> : state === 'error' ? <Recovery message="تعذر تحميل الفئة المنشورة أو تغيّر الإصدار النشط." retry={() => void load(false)} /> : detail ? <><dl className="admin-detail-list"><div><dt>الاسم المنشور</dt><dd>{text(detail.labelAr)}</dd></div><div><dt>المعرف</dt><dd><bdi dir="ltr">{text(detail.id)}</bdi></dd></div>{publishedCategoryTopic(detail) ? <div><dt>الموضوع (تجميع للتصفح)</dt><dd>{publishedCategoryTopic(detail)}</dd></div> : null}<div><dt>الأسئلة المنشورة</dt><dd>{text(detail.approvedCount)}</dd></div><div><dt>جاهزية اللعب</dt><dd>{publishedReadiness(detail.runtimeReadiness)}</dd></div></dl><p className="admin-hint">الموضوع تجميع تصفح مشتق من التصنيف المحلي، وليس حقلاً محفوظاً في الإصدار المنشور.</p>{Number(detail.approvedCount) === 0 ? <p className="admin-empty">لا توجد أسئلة منشورة في هذه الفئة ضمن هذا الإصدار.</p> : <Link className="button button--primary" to={publishedQuestionsPath(detail.id, detail.releaseId)} onClick={event => protectQuestionNavigation(event, publishedQuestionsPath(detail.id, detail.releaseId))}>عرض أسئلة هذه الفئة ({text(detail.approvedCount)})</Link>}<section className="admin-published-detail" aria-labelledby="category-correction-title"><div><p className="eyebrow">تصحيح داخلي</p><h2 id="category-correction-title">مسودة تصحيح الفئة</h2></div><p className="admin-notice">هذه مسودة تصحيح داخلية؛ لا يراها اللاعبون. يلزم إصدار لاحق ومراجعة منفصلة قبل أن يظهر أي تغيير في اللعب.</p>{correctionDraft ? <dl className="admin-detail-list"><div><dt>الحالة</dt><dd><Status value={correctionDraft.status} /></dd></div><div><dt>المراجعة</dt><dd>{text(correctionDraft.revision)}</dd></div><div><dt>اسم مقترح</dt><dd>{text(correctionDraft.proposedLabelAr)}</dd></div></dl> : <p className="admin-hint">لا توجد مسودة تصحيح محفوظة لهذه الفئة في الإصدار النشط.</p>}{canEditCorrection ? <form className="admin-form" onSubmit={saveCorrection}><fieldset disabled={saveState === 'saving'}><legend>بيانات مسودة التصحيح</legend><label htmlFor="admin-category-proposed-label">الاسم العربي المقترح<input id="admin-category-proposed-label" value={proposedLabelAr} maxLength={160} required aria-describedby="admin-category-proposed-label-guidance" onChange={event => { setProposedLabelAr(event.target.value); admin?.setDirty(true); }} /></label><p id="admin-category-proposed-label-guidance" className="admin-hint">يلزم اسم عربي مقترح قبل حفظ مسودة التصحيح.</p><label htmlFor="admin-category-internal-note">ملاحظة التصحيح الداخلية<textarea id="admin-category-internal-note" value={internalNote} maxLength={2000} required aria-describedby="admin-category-internal-note-guidance" onChange={event => { setInternalNote(event.target.value); admin?.setDirty(true); }} /></label><p id="admin-category-internal-note-guidance" className="admin-hint">يلزم وصف داخلي موجز لسبب التصحيح؛ لا يظهر للاعبين.</p></fieldset><p aria-live="polite" className="admin-form-status">{saveMessage}</p><button className="button button--primary" type="submit" disabled={saveState === 'saving'}>{saveState === 'saving' ? 'جارٍ الحفظ…' : 'حفظ مسودة التصحيح'}</button></form> : <p className="admin-notice">{correctionGateStaged && capabilities(admin?.session ?? null, 'categories.write') ? 'مسودات تصحيح الفئات في وضع مرحلي؛ لا يمكن حفظها حتى يفتح الخادم بوابتها المخصصة.' : 'هذه الجلسة للقراءة فقط؛ لا تملك صلاحية عرض الملاحظة الداخلية أو حفظ تصحيح الفئة.'}</p>}</section></> : null}</AdminSurface>;
  return <AdminSurface title="فئات الإصدار المنشور" description="كل فئات الإصدار النشط ظاهرة هنا، بما فيها الفئات المحجوبة عن أنماط اللعب."><AdminPublishedCategoryList key={releaseId ?? 'pending'} items={items} nextCursor={nextCursor} releaseId={releaseId} state={state} loadMore={() => void load(true)} retry={() => void load(false)} /></AdminSurface>;
}

function AdminPublishedCategoryList({ items, nextCursor, releaseId, state, loadMore, retry }: {
  items: Row[];
  nextCursor: string | null;
  releaseId: string | undefined;
  state: 'loading' | 'ready' | 'error';
  loadMore: () => void;
  retry: () => void;
}) {
  const [questionType, setQuestionType] = useState<CategoryQuestionType | 'all'>('all');
  const [typeCounts, setTypeCounts] = useState<Map<string, Record<CategoryQuestionType, number>> | null>(null);
  const [typeStatus, setTypeStatus] = useState<'loading' | 'ready' | 'unavailable'>('loading');
  const [extraItems, setExtraItems] = useState<Row[]>([]);
  const [loadingAll, setLoadingAll] = useState(false);
  const [typeError, setTypeError] = useState('');
  const [localTypeIndexPreview, setLocalTypeIndexPreview] = useState(false);
  const [visibleLimit, setVisibleLimit] = useState(50);
  const requestId = useRef(0);

  useEffect(() => {
    if (!releaseId) return;
    let live = true;
    setTypeStatus('loading');
    void getPublishedCategoryQuestionTypes().then(catalog => {
      if (!live) return;
      if (catalog.releaseId !== releaseId || catalog.categories.some(category => !category.questionTypeCounts)) {
        setTypeStatus('unavailable');
        return;
      }
      setTypeCounts(new Map(catalog.categories.map(category => [category.id, category.questionTypeCounts!])));
      setLocalTypeIndexPreview(catalog.localTypeIndexPreview === true);
      setTypeStatus('ready');
    }).catch(() => { if (live) setTypeStatus('unavailable'); });
    return () => { live = false; };
  }, [releaseId]);

  const selectQuestionType = async (value: CategoryQuestionType | 'all') => {
    const token = ++requestId.current;
    setVisibleLimit(50);
    setTypeError('');
    if (value === 'all') {
      setQuestionType('all');
      setExtraItems([]);
      setLoadingAll(false);
      return;
    }
    if (!typeCounts || !releaseId) return;
    setQuestionType(value);
    if (!nextCursor) return;
    setLoadingAll(true);
    try {
      const remaining: Row[] = [];
      let cursor: string | null = nextCursor;
      while (cursor) {
        const page = await listPublishedCategories({ limit: 100, cursor, releaseId });
        if (requestId.current !== token) return;
        if (page.releaseId !== releaseId) throw new Error('ACTIVE_RELEASE_CHANGED');
        remaining.push(...page.items);
        cursor = page.nextCursor;
      }
      setExtraItems(remaining);
    } catch {
      if (requestId.current !== token) return;
      setQuestionType('all');
      setExtraItems([]);
      setTypeError('تعذر تحميل جميع الفئات لهذا النمط؛ بقيت القائمة دون تصفية. أعد المحاولة.');
    } finally {
      if (requestId.current === token) setLoadingAll(false);
    }
  };

  const filtered = (questionType === 'all' ? items : [...items, ...extraItems].filter(item =>
    (typeCounts?.get(String(item.id))?.[questionType] ?? 0) > 0));
  const shown = filtered.slice(0, visibleLimit);
  const canLoadMore = questionType === 'all' ? Boolean(nextCursor) : filtered.length > visibleLimit;
  return <>
    <div className="admin-toolbar">
      <label>نمط السؤال
        <select aria-label="نمط السؤال في الفئات" value={questionType} disabled={state !== 'ready' || loadingAll || typeStatus !== 'ready'} onChange={event => void selectQuestionType(event.target.value as CategoryQuestionType | 'all')}>
          <option value="all">كل الأنماط</option>
          {categoryQuestionTypes.map(type => <option key={type.id} value={type.id}>{type.labelAr}</option>)}
        </select>
      </label>
      {questionType !== 'all' ? <button className="button button--secondary" type="button" onClick={() => void selectQuestionType('all')}>مسح التصفية</button> : null}
    </div>
    {typeStatus === 'unavailable' ? <p className="admin-hint">تصنيف أنماط الأسئلة غير متاح لهذا الإصدار حالياً؛ تبقى كل الفئات ظاهرة.</p> : null}
    {localTypeIndexPreview ? <p className="admin-hint">تصفية محلية مبنية على فهرس هذا الإصدار المراجع؛ لم يُنشر الفهرس بعد في الإنتاج.</p> : null}
    {loadingAll ? <p className="admin-hint" role="status">جارٍ تحميل كل فئات الإصدار قبل تطبيق التصفية…</p> : null}
    {typeError ? <p className="admin-notice" role="alert">{typeError}</p> : null}
    {state === 'loading' || loadingAll ? <LoadingRows /> : state === 'error' ? <Recovery message="تعذر تحميل فهرس الفئات؛ لم تُعرض حالة صفرية بديلة." retry={retry} /> : shown.length ? <div className="admin-table-wrap"><div className="admin-table admin-table--categories" role="table" aria-label="فئات الإصدار المنشور"><div className="admin-table__row admin-table__row--head" role="row"><b role="columnheader">الفئة</b><b role="columnheader">الأسئلة</b><b role="columnheader">جاهزية اللعب</b><b role="columnheader">الإجراءات</b></div>{shown.map(item => <div className="admin-table__row" role="row" key={String(item.id)}><span role="cell">{text(item.labelAr)} <small><bdi dir="ltr">{text(item.id)}</bdi></small></span><span role="cell">{text(item.approvedCount)}</span><span role="cell">{publishedReadiness(item.runtimeReadiness)}</span><span role="cell" className="admin-inline-actions"><Link className="text-link" to={`/admin/categories/${encodeURIComponent(String(item.id))}${releaseId ? `?releaseId=${encodeURIComponent(releaseId)}` : ''}`}>عرض الفئة</Link><Link className="text-link" to={publishedQuestionsPath(item.id, releaseId)}>عرض الأسئلة</Link></span></div>)}</div></div> : <p className="admin-empty">{questionType === 'all' ? 'لا توجد فئات منشورة ضمن نطاقك.' : 'لا توجد فئات منشورة مطابقة لهذا النمط ضمن نطاقك.'}</p>}
    {state === 'ready' && !loadingAll && canLoadMore ? <button className="button button--secondary" type="button" onClick={() => { setVisibleLimit(limit => limit + 50); if (questionType === 'all' && nextCursor) loadMore(); }}>تحميل الصفحة التالية</button> : null}
    <p className="admin-hint">الإصدار: <bdi dir="ltr">{releaseId ?? 'جارٍ التحقق'}</bdi></p>
  </>;
}

type PublishedMediaVariant = 'question' | 'answer';

function PublishedMediaPreview({ media, variant, questionId, releaseId }: { media: Row; variant: PublishedMediaVariant; questionId: string; releaseId: string }) {
  const label = variant === 'question' ? 'السؤال' : 'الإجابة';
  const kind = media.type === 'video' || media.contentType === 'video/mp4' ? 'video' : media.type === 'image' || media.contentType === 'image/png' || media.contentType === 'image/jpeg' ? 'image' : null;
  const [preview, setPreview] = useState<{ url: string; type: string } | null>(null);
  const [state, setState] = useState<'idle' | 'loading' | 'ready' | 'error'>(kind === 'image' ? 'loading' : 'idle');
  const [error, setError] = useState('');
  const [retry, setRetry] = useState(0);
  const mounted = useRef(true);

  useEffect(() => {
    mounted.current = true;
    return () => { mounted.current = false; };
  }, []);

  useEffect(() => {
    if (kind !== 'image') return;
    let current = true;
    setState('loading');
    setError('');
    void getPublishedQuestionMedia(questionId, releaseId, variant).then(result => {
      if (!current) return;
      setPreview({ url: result.url, type: result.type });
      setState('ready');
    }).catch(reason => {
      if (!current) return;
      setState('error');
      setError(mediaPreviewError(reason));
    });
    return () => { current = false; };
  }, [kind, questionId, releaseId, variant, media.mediaId, retry]);

  const openVideo = async () => {
    if (state === 'loading') return;
    setState('loading');
    setError('');
    try {
      const result = await getPublishedQuestionMedia(questionId, releaseId, variant);
      if (!mounted.current) return;
      setPreview({ url: result.url, type: result.type });
      setState('ready');
    } catch (reason) {
      if (!mounted.current) return;
      setState('error');
      setError(mediaPreviewError(reason));
    }
  };

  if (!kind) return <p className="admin-hint">نوع هذا الوسيط غير مدعوم للعرض داخل الصفحة.</p>;

  return <div className="admin-published-media">
    <p className="admin-published-media__label">{kind === 'video' ? 'فيديو' : 'صورة'} {label}</p>
    {kind === 'video' ? (
      preview ? <video className="admin-media-preview admin-media-preview--video" aria-label={`فيديو ${label}`} controls controlsList="nodownload" autoPlay playsInline preload="metadata" src={preview.url} onError={() => { setPreview(null); setState('error'); setError('تعذر تشغيل هذا الفيديو داخل الصفحة.'); }} /> :
        <button className="admin-media-play" type="button" onClick={() => void openVideo()} disabled={state === 'loading'}>
          <span className="admin-media-play__icon" aria-hidden="true">▶</span>
          <span>{state === 'loading' ? 'جارٍ تجهيز الفيديو…' : state === 'error' ? `أعد محاولة عرض فيديو ${label}` : `شاهد فيديو ${label}`}</span>
          <small>يُعرض هنا داخل {label}، دون تنزيل ملف.</small>
        </button>
    ) : (
      preview ? <img className="admin-media-preview admin-media-preview--image" src={preview.url} alt={typeof media.altAr === 'string' && media.altAr ? media.altAr : `صورة ${label}`} onError={() => { setPreview(null); setState('error'); setError('تعذر عرض هذه الصورة داخل الصفحة.'); }} /> :
        state === 'error' ? <button className="button button--secondary" type="button" onClick={() => setRetry(current => current + 1)}>إعادة محاولة عرض صورة {label}</button> :
          <div className="admin-media-loading" role="status">جارٍ عرض صورة {label}…</div>
    )}
    {state === 'error' ? <p className="admin-field-error" role="alert">{error}</p> : null}
    {typeof media.altAr === 'string' && media.altAr ? <p className="admin-published-media__caption">{media.altAr}</p> : null}
    <details className="admin-published-media__details">
      <summary>بيانات الوسيط</summary>
      <dl><div><dt>المعرف</dt><dd><bdi dir="ltr">{text(media.mediaId)}</bdi></dd></div><div><dt>النوع</dt><dd>{text(media.contentType ?? media.type)}</dd></div></dl>
    </details>
  </div>;
}

function mediaPreviewError(reason: unknown) {
  const code = String((reason as { code?: unknown })?.code ?? '');
  return code.includes('resource-exhausted')
    ? 'حجم الوسيط يتجاوز حد العرض داخل لوحة الإدارة (1 ميغابايت).'
    : 'تعذر عرض الوسيط؛ لم يكتمل التحقق من ارتباطه بالإصدار أو لا تملك نطاقه.';
}

function publicCategoryCover(categoryId: string) {
  const adminEntry = adminPublishedCategoryCovers.categories.find(item => item.categoryId === categoryId);
  if (adminEntry?.publishable === true) return { web320: adminEntry.web320, altAr: adminEntry.altAr };
  const sourceEntry = sourceCategoryCovers.categories.find(item => item.categoryId === categoryId);
  return sourceEntry?.cover.publishable === true ? { web320: sourceEntry.cover.web320, altAr: `غلاف فئة ${categoryId}` } : null;
}

function PublishedQuestionInspectionDetail({ value }: { value: Row }) {
  const admin = useAdmin(); const navigate = useNavigate(); const questionId = String(value.id ?? ''); const releaseId = String(value.releaseId ?? ''); const categoryId = String(value.categoryId ?? '');
  const identity = `${releaseId}:${questionId}`; const identityRef = useRef(identity); const operationRef = useRef<string | null>(null); const pendingRef = useRef(false);
  const [saving, setSaving] = useState(false); const [notice, setNotice] = useState(''); const [coverFailed, setCoverFailed] = useState(false); const [reviewed, setReviewed] = useState(value.inspection && typeof value.inspection === 'object' && (value.inspection as Row).reviewed === true);
  useEffect(() => { identityRef.current = identity; operationRef.current = null; pendingRef.current = false; setSaving(false); setNotice(''); setCoverFailed(false); setReviewed(value.inspection && typeof value.inspection === 'object' && (value.inspection as Row).reviewed === true); return () => { identityRef.current = ''; }; }, [identity, value.inspection]);
  const canInspect = capabilities(admin?.session ?? null, 'questions.inspect'); const inspectionMode = admin?.session.publishedQuestionInspectionMode ?? 'staged';
  const markAndAdvance = async () => {
    if (!questionId || !releaseId || pendingRef.current || saving || reviewed || !canInspect || inspectionMode !== 'enabled') return;
    const submittedIdentity = identity; const operationId = operationRef.current ?? crypto.randomUUID(); operationRef.current = operationId;
    pendingRef.current = true;
    setSaving(true); setNotice('جارٍ تسجيل الفحص التشغيلي…');
    try {
      await markPublishedQuestionInspected({ id: questionId, releaseId, operationId });
      if (identityRef.current !== submittedIdentity) return;
      operationRef.current = null; setReviewed(true);
      const next = typeof value.nextQuestionId === 'string' ? value.nextQuestionId : '';
      if (next) { navigate(publishedQuestionPath(next, releaseId)); return; }
      setNotice('حُفظت علامة الفحص. وصلت إلى آخر سؤال في هذه الفئة.');
    } catch (error) {
      if (identityRef.current !== submittedIdentity) return;
      setNotice(isConflict(error) ? 'تغيّر الإصدار أو السؤال أثناء الحفظ؛ حدّث الصفحة قبل المتابعة.' : 'تعذر تأكيد الحفظ. أعد المحاولة؛ ستُستخدم العملية نفسها حتى لا يتكرر التسجيل.');
    } finally { if (identityRef.current === submittedIdentity) { pendingRef.current = false; setSaving(false); } }
  };
  const cover = publicCategoryCover(categoryId);
  return <article className="admin-published-detail admin-published-inspection">
    <header className="admin-published-hero">
      <p className="eyebrow">إدارة الخلية - تفاصيل السؤال المنشور</p>
      <div className="admin-published-hero__row">
        <div className="admin-published-category" aria-labelledby="admin-published-category-title">
          {cover && !coverFailed ? <img src={`/${cover.web320}`} alt={cover.altAr} onError={() => setCoverFailed(true)} /> : <div className="admin-published-category__fallback" role="img" aria-label="لا تتوفر صورة عامة منشورة لهذه الفئة">لا تتوفر صورة عامة منشورة لهذه الفئة</div>}
          <div><h1 id="admin-published-category-title">{text(value.categoryLabelAr)}</h1><p>قراءة من الإصدار المنشور الثابت. لا يمكن تحرير هذا السجل من لوحة الإدارة.</p></div>
        </div>
        <Link className="text-link admin-published-hero__back" to={publishedQuestionsPath(value.categoryId, value.releaseId)}>العودة إلى أسئلة الفئة</Link>
      </div>
    </header>
    <div className="admin-published-reviewbar">
      <nav className="admin-published-navigation" aria-label="تنقل أسئلة الفئة">
        {typeof value.previousQuestionId === 'string' ? <Link className="button button--secondary" to={publishedQuestionPath(value.previousQuestionId, releaseId)}>السؤال السابق</Link> : <span className="admin-hint">هذا أول سؤال في الفئة.</span>}
        {typeof value.nextQuestionId === 'string' ? <Link className="button button--secondary" to={publishedQuestionPath(value.nextQuestionId, releaseId)}>السؤال التالي</Link> : <span className="admin-hint">هذا آخر سؤال في الفئة.</span>}
      </nav>
      <section className="admin-published-inspection__controls" aria-labelledby="admin-inspection-heading">
        <div><p className="eyebrow">فحص تشغيلي</p><h2 id="admin-inspection-heading">{reviewed ? 'تم فحص هذا السؤال' : 'لم يُسجل فحص لهذا السؤال بعد'}</h2><p className="admin-hint">علامة فحص فقط؛ لا تغيّر المحتوى أو النشر.</p></div>
        {reviewed ? <Status value="completed">تم الفحص</Status> : canInspect && inspectionMode === 'enabled' ? <button className="button button--primary" type="button" disabled={saving} onClick={() => void markAndAdvance()}>{saving ? 'جارٍ الحفظ…' : 'تسجيل الفحص والانتقال'}</button> : <p className="admin-notice">{canInspect ? 'تسجيل الفحص في وضع مرحلي حتى تفتح بوابته المخصصة.' : 'هذه الجلسة للقراءة فقط ولا تملك صلاحية تسجيل الفحص.'}</p>}
        {notice ? <p className="admin-form-status" aria-live="polite">{notice}</p> : null}
      </section>
    </div>
    <PublishedQuestionDetail value={value} />
  </article>;
}

export function PublishedQuestionDetail({ value }: { value: Row }) {
  const questionMedia = value.media && typeof value.media === 'object' ? value.media as Row : null;
  const answerMedia = value.answerMedia && typeof value.answerMedia === 'object' ? value.answerMedia as Row : null;
  const questionId = String(value.id ?? '');
  const releaseId = String(value.releaseId ?? '');
  const aliases = Array.isArray(value.acceptedAnswers) ? value.acceptedAnswers.filter(answer => typeof answer === 'string' && answer !== value.canonicalAnswer) : [];
  const distinctHeader = typeof value.headerAr === 'string' && value.headerAr.trim() && value.headerAr.trim() !== String(value.categoryLabelAr ?? '').trim();

  return <article className="admin-published-detail">
    {distinctHeader ? <header className="admin-published-detail__header">
      <p className="eyebrow">السجل المنشور</p>
      <h2>{text(value.headerAr)}</h2>
    </header> : null}
    <dl className="admin-published-facts">
      <div><dt>الفئة</dt><dd><bdi dir="ltr">{text(value.categoryId)}</bdi></dd></div>
      <div><dt>النمط</dt><dd><Status value={value.modality} /></dd></div>
      {typeof value.targetLetter === 'string' && value.targetLetter && value.targetLetter !== 'category-only' ? <div><dt>الحرف المستهدف</dt><dd>{value.targetLetter}</dd></div> : null}
      {typeof value.points === 'number' && Number.isFinite(value.points) ? <div><dt>النقاط</dt><dd>{value.points}</dd></div> : null}
      <div><dt>الصعوبة</dt><dd>{typeof value.difficulty === 'string' && value.difficulty ? value.difficulty : 'غير مخزنة في هذا الإصدار'}</dd></div>
    </dl>
    <section className="admin-published-panel admin-published-panel--question" aria-labelledby="admin-published-question-heading">
      <div className="admin-published-panel__heading"><span className="admin-published-panel__number" aria-hidden="true">١</span><h2 id="admin-published-question-heading">السؤال</h2></div>
      <p className="admin-published-panel__copy">{text(value.promptAr)}</p>
      {questionMedia?.mediaId ? <PublishedMediaPreview key={`${releaseId}:${questionId}:question:${String(questionMedia.mediaId)}`} media={questionMedia} variant="question" questionId={questionId} releaseId={releaseId} /> : null}
    </section>
    <section className="admin-published-panel admin-published-panel--answer" aria-labelledby="admin-published-answer-heading">
      <div className="admin-published-panel__heading"><span className="admin-published-panel__number" aria-hidden="true">٢</span><h2 id="admin-published-answer-heading">الإجابة</h2></div>
      <p className="admin-published-panel__copy">{text(value.canonicalAnswer)}</p>
      {aliases.length ? <p className="admin-published-aliases"><strong>بدائل مقبولة</strong> {aliases.map(text).join('، ')}</p> : null}
      {answerMedia?.mediaId ? <PublishedMediaPreview key={`${releaseId}:${questionId}:answer:${String(answerMedia.mediaId)}`} media={answerMedia} variant="answer" questionId={questionId} releaseId={releaseId} /> : null}
    </section>
    <p className="admin-published-detail__footnote">هذا السؤال من الإصدار المنشور الثابت. تعديل المحتوى يمر عبر مسودة ومراجعة منفصلتين.</p>
  </article>;
}
const listLoaders: Record<string, (data?: Record<string, unknown>) => Promise<{ items: Row[]; nextCursor: string | null }>> = { drafts: listQuestions, reviews: listReviews, releases: listReleases, rooms: listRooms, audit: listAudit };
const detailLoaders: Record<string, (id: string) => Promise<Row>> = { drafts: getQuestion, reviews: getReview, releases: getRelease, rooms: getRoom };
function rowCells(section: string, item: Row, categoryNames: Record<string, string> = {}): Array<{ label: string; value: ReactNode }> {
  const category = (categoryId: unknown) => { const id = String(categoryId ?? ''); const title = categoryNames[id]; return <>{title || 'فئة غير معروضة'} {id ? <small><bdi dir="ltr">{id}</bdi></small> : null}</>; };
  if (section === 'drafts') return [{ label: 'العنوان', value: text(item.headerAr) }, { label: 'الحالة', value: <Status value={item.status} /> }, { label: 'الفئة', value: category(item.categoryId) }, { label: 'النمط', value: labelStatus(item.modality) }];
  if (section === 'reviews') return [{ label: 'السؤال', value: text(item.questionId) }, { label: 'الحالة', value: <Status value={item.status} /> }, { label: 'الفئة', value: category(item.categoryId) }, { label: 'المراجعة', value: `#${text(item.revision)}` }];
  if (section === 'categories') return [{ label: 'الفئة', value: text(item.titleAr) }, { label: 'المعرف', value: <bdi dir="ltr">{text(item.id)}</bdi> }, { label: 'الحالة', value: item.enabled === false ? <Status value="disabled" /> : <Status value="enabled" /> }, { label: 'جاهزية اللعب', value: 'غير متاحة من ملخص الفئة' }];
  if (section === 'releases') return [{ label: 'الإصدار', value: text(item.id) }, { label: 'الثبات', value: item.immutable === true ? 'سجل ثابت' : 'غير مثبت' }, { label: 'الأسئلة المعتمدة', value: text(item.approvedCount) }];
  if (section === 'rooms') return [{ label: 'رمز الغرفة', value: <bdi dir="ltr">{text(item.roomCode)}</bdi> }, { label: 'الحالة', value: <Status value={item.lifecycle} /> }, { label: 'الأعضاء', value: text(item.memberCount) }, { label: 'الإصدار', value: text(item.releaseId) }];
  return [{ label: 'الإجراء', value: text(item.action) }, { label: 'الهدف', value: text(item.target) }, { label: 'النتيجة', value: <Status value={item.result} /> }, { label: 'الوقت', value: asDate(item.createdAt) }];
}

export function AdminRecordRoute({ section: explicitSection }: { section?: string } = {}) {
  const params = useParams(); const section = explicitSection ?? params.section ?? ''; const id = params.id; const admin = useAdmin(); const [state, setState] = useState<'loading' | 'ready' | 'error'>('loading'); const [items, setItems] = useState<Row[]>([]); const [categoryNames, setCategoryNames] = useState<Record<string, string>>({}); const [nextCursor, setNextCursor] = useState<string | null>(null); const [filter, setFilter] = useState(''); const [statusFilter, setStatusFilter] = useState(''); const [categoryFilter, setCategoryFilter] = useState(''); const [modalityFilter, setModalityFilter] = useState(''); const [notice, setNotice] = useState(''); const [pending, setPending] = useState(''); const [roomReason, setRoomReason] = useState(''); const [reviewReasons, setReviewReasons] = useState<Record<string, string>>({});
  const loader = listLoaders[section];
  const load = async (append = false) => { setState('loading'); setNotice(''); try { const detailLoader = id ? detailLoaders[section] : undefined; const result = detailLoader && id ? { items: [await detailLoader(id)], nextCursor: null } : loader ? await loader({ limit: 50, ...(append && nextCursor ? { cursor: nextCursor } : {}) }) : section === 'health' ? { items: [await getHealth()], nextCursor: null } : { items: [], nextCursor: null }; setItems(previous => append ? [...previous, ...result.items] : result.items); setNextCursor(result.nextCursor); setState('ready'); } catch { setState('error'); } };
  useEffect(() => { setFilter(''); setStatusFilter(''); setCategoryFilter(''); setModalityFilter(''); setNextCursor(null); void load(false); }, [section, id]);
  useEffect(() => { if (section !== 'drafts' && section !== 'reviews') return; let live = true; void listCategories({ limit: 100 }).then(page => { if (live) setCategoryNames(Object.fromEntries(page.items.map(category => [String(category.id), String(category.titleAr || category.id)]))); }).catch(() => live && setCategoryNames({})); return () => { live = false; }; }, [section]);
  const filtered = useMemo(() => { const needle = filter.trim().toLocaleLowerCase('ar'); return items.filter(item => { if (section === 'drafts' && ((statusFilter && String(item.status ?? '') !== statusFilter) || (categoryFilter && String(item.categoryId ?? '') !== categoryFilter) || (modalityFilter && String(item.modality ?? '') !== modalityFilter))) return false; if (!needle) return true; const visibleText = [String(item.id ?? ''), text(item.headerAr), labelStatus(item.status), categoryNames[String(item.categoryId ?? '')] ?? String(item.categoryId ?? ''), labelStatus(item.modality)].join(' ').toLocaleLowerCase('ar'); return visibleText.includes(needle); }); }, [categoryFilter, categoryNames, filter, items, modalityFilter, section, statusFilter]);
  const can = (capability: AdminCapability) => capabilities(admin?.session ?? null, capability);
  const canMutate = (capability: AdminCapability) => can(capability) && admin?.session.mutationMode === 'enabled';
  const requestChanges = async (item: Row) => { const reason = reviewReasons[String(item.id)]?.trim(); if (!reason) { setNotice('اكتب سبب طلب التعديلات قبل الإرسال.'); return; } setPending(String(item.id)); try { await decideReview({ id: item.id, operationId: crypto.randomUUID(), expectedRevision: item.revision, decision: 'changes_requested', reason }); setNotice('سُجل طلب التعديلات. حُدِّث السجل من الخادم.'); await load(false); } catch (error) { setNotice(isConflict(error) ? 'تعارض مراجعة: حدّث السجل قبل إعادة القرار.' : 'تعذر إرسال القرار أو لا تملك صلاحية المراجعة.'); } finally { setPending(''); } };
  const actOnRoom = async (item: Row, action: 'pause' | 'resume' | 'close') => { if (!roomReason.trim()) { setNotice('اكتب سبباً تشغيلياً قبل تنفيذ الإجراء.'); return; } if (action === 'close' && !window.confirm('سيُغلق هذا السجل التشغيلي. هل تريد المتابعة؟')) return; setPending(String(item.id)); try { await roomAction({ id: item.id, operationId: crypto.randomUUID(), expectedRevision: item.revision, action, reason: roomReason.trim() }); setRoomReason(''); setNotice('وصلت العملية إلى الخادم؛ حُدِّثت بيانات الغرفة.'); await load(false); } catch { setNotice('رُفض الإجراء أو أصبحت مراجعة الغرفة قديمة. حدّث السجل وأعد المحاولة.'); } finally { setPending(''); } };
  const stage = async (item: Row) => { setPending(String(item.id)); try { const result = await releaseStage({ id: item.id, operationId: crypto.randomUUID(), expectedRevision: item.revision ?? 0 }); setNotice(result.replayed ? 'هذه العملية مسجلة سابقاً.' : 'مسار الإصدار محجوب بالخادم إلى أن تتحقق متطلبات التوقيع.'); } catch { setNotice('تعذر طلب مرحلة الإصدار أو لا تملك الصلاحية.'); } finally { setPending(''); } };
  const headers = items[0] ? rowCells(section, items[0], categoryNames).map(cell => cell.label) : [];
  return <AdminSurface title={titles[section] ?? 'سجل إداري'} description={section === 'health' ? 'حالة الخدمات والإصدار النشط كما يردان من الخادم.' : id ? 'تفاصيل سجل خادم مقيدة بنطاق الصلاحية.' : 'البحث المحلي يقتصر على السجلات المحمّلة؛ المرشحات المعتمدة على الخادم ظاهرة في بنك الإصدار.'}>{section === 'health' && state === 'ready' && items[0] ? <HealthSummary value={items[0]} /> : null}{section !== 'health' ? <div className="admin-toolbar"><label>تصفية السجلات المحمّلة<input aria-label="تصفية السجلات" value={filter} onChange={event => setFilter(event.target.value)} placeholder="بحث محلي في السجلات المحمّلة" disabled={state === 'loading'} /></label>{section === 'drafts' ? <><label>حالة المسودة<select aria-label="حالة السؤال" value={statusFilter} onChange={event => setStatusFilter(event.target.value)} disabled={state === 'loading'}><option value="">كل الحالات</option>{['draft', 'ready_for_review', 'in_review', 'changes_requested', 'approved', 'archived'].map(value => <option key={value} value={value}>{labelStatus(value)}</option>)}</select></label><label>فئة المسودة<select aria-label="فئة السؤال" value={categoryFilter} onChange={event => setCategoryFilter(event.target.value)} disabled={state === 'loading'}><option value="">كل الفئات</option>{Object.entries(categoryNames).map(([id, title]) => <option key={id} value={id}>{title || id}</option>)}</select></label><label>نمط السؤال<select aria-label="نمط السؤال" value={modalityFilter} onChange={event => setModalityFilter(event.target.value)} disabled={state === 'loading'}><option value="">كل الأنماط</option>{['classic', 'image', 'charades'].map(value => <option key={value} value={value}>{labelStatus(value)}</option>)}</select></label></> : null}<span className="admin-count" aria-live="polite">{filtered.length} من {items.length} سجل محمّل</span><button className="button button--secondary" type="button" onClick={() => { setFilter(''); setStatusFilter(''); setCategoryFilter(''); setModalityFilter(''); }} disabled={!filter && !statusFilter && !categoryFilter && !modalityFilter}>مسح التصفية</button><button className="button button--secondary" type="button" onClick={() => void load(false)} disabled={state === 'loading'}>تحديث</button>{section === 'drafts' && !id && canMutate('questions.write') ? <Link className="button button--primary" to="/admin/drafts/new">سؤال جديد</Link> : null}</div> : null}{section === 'rooms' && id && canMutate('rooms.act') ? <label className="admin-action-reason">سبب الإجراء التشغيلي<textarea value={roomReason} maxLength={1000} onChange={event => setRoomReason(event.target.value)} placeholder="سبب مطلوب ويحفظ في سجل التدقيق" /></label> : null}{admin?.session.mutationMode === 'staged' && ['drafts', 'reviews', 'releases', 'rooms', 'settings'].includes(section) ? <p className="admin-notice">هذه البيئة في وضع مرحلي؛ إجراءات التغيير معطلة حتى يفتحها الخادم.</p> : null}{notice ? <p className="admin-notice" aria-live="polite">{notice}</p> : null}{state === 'loading' ? <LoadingRows /> : state === 'error' ? <Recovery message="تعذر التحميل أو انتهت الصلاحية." retry={() => void load(false)} /> : section !== 'health' && filtered.length ? <div className="admin-table-wrap"><div className="admin-table" role="table" aria-label={titles[section]}><div className="admin-table__row admin-table__row--head" role="row">{headers.map(header => <b role="columnheader" key={header}>{header}</b>)}<b role="columnheader">الإجراء</b></div>{filtered.map(item => <div role="row" className="admin-table__row" key={String(item.id)}>{rowCells(section, item, categoryNames).map(cell => <span role="cell" data-label={cell.label} key={cell.label}>{cell.value}</span>)}<div role="cell" data-label="الإجراء" className="admin-table__actions">{['drafts', 'reviews', 'releases', 'rooms'].includes(section) && !id ? <Link className="text-link" to={`/admin/${section}/${encodeURIComponent(String(item.id))}`}>فتح</Link> : null}{section === 'reviews' && canMutate('reviews.decide') ? <><label className="sr-only" htmlFor={`review-reason-${item.id}`}>سبب طلب التعديلات</label><textarea id={`review-reason-${item.id}`} value={reviewReasons[String(item.id)] ?? ''} onChange={event => setReviewReasons(current => ({ ...current, [String(item.id)]: event.target.value }))} placeholder="سبب طلب التعديلات" /><button className="button button--secondary" type="button" disabled={pending === String(item.id)} onClick={() => void requestChanges(item)}>{pending === String(item.id) ? 'جارٍ الإرسال…' : 'طلب تعديلات'}</button></> : null}{section === 'rooms' && id && canMutate('rooms.act') ? <div className="admin-inline-actions"><button className="button button--secondary" type="button" disabled={pending === String(item.id)} onClick={() => void actOnRoom(item, item.paused ? 'resume' : 'pause')}>{item.paused ? 'استئناف' : 'إيقاف مؤقت'}</button><button className="button button--danger" type="button" disabled={pending === String(item.id)} onClick={() => void actOnRoom(item, 'close')}>إغلاق الغرفة</button></div> : null}{section === 'releases' && canMutate('releases.stage') ? <button className="button button--secondary" type="button" disabled={pending === String(item.id)} onClick={() => void stage(item)}>فحص حالة المرحلة</button> : null}</div></div>)}</div></div> : section !== 'health' ? <div className="admin-empty"><p>{filter ? 'لا توجد نتائج ضمن الصفحة المحمّلة.' : 'لا توجد سجلات ضمن نطاقك.'}</p></div> : null}{nextCursor && !id ? <button className="button button--secondary" type="button" disabled={state === 'loading'} onClick={() => void load(true)}>تحميل الصفحة التالية</button> : null}</AdminSurface>;
}

function fromDetail(detail: Row | null): Draft { const sources = Array.isArray(detail?.sources) ? detail.sources.filter(source => source && typeof source === 'object').map(source => ({ ...emptySource(), ...(source as Source) })) : [emptySource()]; return { categoryId: String(detail?.categoryId ?? ''), modality: detail?.modality === 'image' || detail?.modality === 'charades' ? detail.modality : 'classic', headerAr: String(detail?.headerAr ?? ''), promptAr: String(detail?.promptAr ?? ''), canonicalAnswer: String(detail?.canonicalAnswer ?? ''), acceptedAnswers: Array.isArray(detail?.acceptedAnswers) ? detail.acceptedAnswers.join('\n') : '', sources: sources.length ? sources : [emptySource()], ready: detail?.status === 'ready_for_review' }; }
function specialistRoles(modality: Draft['modality']) { return modality === 'image' ? ['fact_reviewer', 'language_reviewer', 'image_rights_reviewer'] : modality === 'charades' ? ['fact_reviewer', 'language_reviewer', 'charades_performance_reviewer', 'charades_originality_reviewer', 'charades_cultural_suitability_reviewer'] : ['fact_reviewer', 'language_reviewer']; }

export function AdminQuestionEditorRoute() { const { questionId } = useParams(); return <AdminQuestionEditor key={questionId ?? 'new'} questionId={questionId} />; }

function AdminQuestionEditor({ questionId }: { questionId?: string }) {
  const navigate = useNavigate(); const admin = useAdmin(); const [newRecordId] = useState(() => crypto.randomUUID()); const recordId = questionId ?? newRecordId; const [loadedRecordId, setLoadedRecordId] = useState<string | null>(questionId ? null : newRecordId); const [draft, setDraft] = useState<Draft>(blankDraft); const [categories, setCategories] = useState<Category[]>([]); const [categoryState, setCategoryState] = useState<'loading' | 'ready' | 'empty' | 'error'>('loading'); const [revision, setRevision] = useState(0); const [status, setStatus] = useState(questionId ? 'جارٍ تحميل السؤال…' : 'مسودة جديدة غير محفوظة'); const [operation, setOperation] = useState<'idle' | 'save' | 'validate' | 'review'>('idle'); const [errors, setErrors] = useState<Record<string, string>>({}); const setDirtyRef = useRef(admin?.setDirty); const editable = capabilities(admin?.session ?? null, 'questions.write') && admin?.session.mutationMode === 'enabled'; const loadReady = loadedRecordId === recordId; const busy = operation !== 'idle'; const saving = busy || !loadReady; const checking = operation === 'validate'; const submittingReview = operation === 'review';
  useEffect(() => { let live = true; void listCategories({ limit: 100 }).then(page => { if (live) { setCategories(page.items); setCategoryState(page.items.length ? 'ready' : 'empty'); } }).catch(() => live && setCategoryState('error')); return () => { live = false; }; }, []);
  useEffect(() => { setDraft(blankDraft()); setRevision(0); setErrors({}); admin?.setDirty(false); if (!questionId) { setLoadedRecordId(newRecordId); setStatus('مسودة جديدة غير محفوظة'); return; } let live = true; setLoadedRecordId(null); setStatus('جارٍ تحميل السؤال…'); void getQuestion(questionId).then(value => { if (live) { setDraft(fromDetail(value)); setRevision(Number(value.revision ?? 0)); setLoadedRecordId(questionId); setStatus('السؤال محمّل.'); } }).catch(() => { if (live) { setLoadedRecordId(null); setStatus('تعذر تحميل السؤال أو لا تملك نطاقه.'); } }); return () => { live = false; }; }, [questionId, newRecordId]);
  useEffect(() => { setDirtyRef.current = admin?.setDirty; }, [admin?.setDirty]);
  useEffect(() => () => setDirtyRef.current?.(false), []);
  useEffect(() => { const warn = (event: BeforeUnloadEvent) => { if (!admin?.dirty) return; event.preventDefault(); event.returnValue = ''; }; window.addEventListener('beforeunload', warn); return () => window.removeEventListener('beforeunload', warn); }, [admin?.dirty]);
  const update = <K extends keyof Draft>(key: K, value: Draft[K]) => { setDraft(current => ({ ...current, [key]: value })); admin?.setDirty(true); setErrors(current => ({ ...current, [String(key)]: '' })); };
  const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!editable || busy || !loadReady) return; const nextErrors: Record<string, string> = {}; if (!draft.categoryId) nextErrors.categoryId = 'اختر فئة قبل الحفظ.'; if (!draft.headerAr.trim()) nextErrors.headerAr = 'العنوان مطلوب.'; if (!draft.promptAr.trim()) nextErrors.promptAr = 'نص السؤال مطلوب.'; if (!draft.canonicalAnswer.trim()) nextErrors.canonicalAnswer = 'الإجابة المرجعية مطلوبة.'; const sources = draft.sources.filter(source => source.sourceUrl.trim() || source.publisher.trim() || source.title.trim()); sources.forEach((source, index) => { if (!/^https:\/\//.test(source.sourceUrl) || !source.publisher.trim() || !source.title.trim()) nextErrors[`source-${index}`] = 'أدخل رابط HTTPS والناشر والعنوان لكل مصدر مضاف.'; }); if (Object.keys(nextErrors).length) { setErrors(nextErrors); setStatus('أكمل الحقول المشار إليها ثم أعد الحفظ.'); const first = Object.keys(nextErrors)[0]; const focusId = first.startsWith('source-') ? `admin-sourceUrl${first === 'source-0' ? '' : `-${first.slice('source-'.length)}`}` : `admin-${first}`; window.setTimeout(() => document.getElementById(focusId)?.focus(), 0); return; }
    const acceptedAnswers = [...new Set([draft.canonicalAnswer.trim(), ...draft.acceptedAnswers.split('\n').map(answer => answer.trim()).filter(Boolean)])]; const payload = { categoryId: draft.categoryId, modality: draft.modality, headerAr: draft.headerAr.trim(), promptAr: draft.promptAr.trim(), canonicalAnswer: draft.canonicalAnswer.trim(), acceptedAnswers, specialistRoles: specialistRoles(draft.modality), sources: sources.map(source => ({ ...source, sourceUrl: source.sourceUrl.trim(), publisher: source.publisher.trim(), title: source.title.trim(), retrievedAt: source.retrievedAt || new Date().toISOString() })), status: draft.ready ? 'ready_for_review' : 'draft' };
    setOperation('save'); setStatus('جارٍ حفظ المسودة…'); try { const result = await saveQuestion({ id: recordId, operationId: crypto.randomUUID(), expectedRevision: revision, draft: payload }); setRevision(result.revision); setStatus('حُفظت المسودة بالخادم.'); if (!questionId) admin?.discardDirty(() => navigate(`/admin/drafts/${encodeURIComponent(recordId)}`, { replace: true })); else admin?.discardDirty(); } catch (error) { setStatus(isConflict(error) ? 'تعارض مراجعة: بقي نصك كما هو. افتح السجل المحدث ثم أعد الحفظ.' : 'تعذر الحفظ؛ بقي النص في النموذج.'); } finally { setOperation('idle'); } };
  const validateSaved = async () => { if (!revision || busy || admin?.dirty || !loadReady) return; setOperation('validate'); try { const result = await validateQuestion(recordId); setStatus(result.valid ? 'اجتاز التحقق الأولي؛ لا يعني ذلك اعتماداً أو نشراً.' : `يلزم استكمال: ${result.errors.join('، ')}`); } catch { setStatus('تعذر التحقق؛ بقيت المسودة في النموذج.'); } finally { setOperation('idle'); } };
  const submitForReview = async () => { if (!revision || busy || admin?.dirty || !loadReady) { if (admin?.dirty) setStatus('احفظ التعديلات أولاً قبل إرسال النسخة المحفوظة للمراجعة.'); return; } setOperation('review'); try { const result = await submitQuestionReview({ id: recordId, operationId: crypto.randomUUID(), expectedRevision: revision }); setRevision(result.revision); setStatus('أُرسل السؤال للمراجعة.'); } catch { setStatus('تعذر الإرسال؛ تحقّق من الجاهزية والمراجعة الحالية.'); } finally { setOperation('idle'); } };
  const sourceHint = draft.modality === 'image' ? 'تتطلب أسئلة الصورة مراجعة حقوق الصورة إضافة إلى مراجعة الحقائق واللغة.' : draft.modality === 'charades' ? 'تتطلب أسئلة التمثيل مراجعات الأداء والأصالة والملاءمة الثقافية.' : 'تتطلب الأسئلة التقليدية مراجعة الحقائق واللغة.';
  return <AdminSurface title={questionId ? 'محرر السؤال' : 'سؤال جديد'} description="تظل المسودة في المتصفح عند فشل الحفظ أو التعارض. تُرسل التغييرات إلى الخادم فقط بعد إقرار الاستجابة."><form className="admin-form admin-question-form" onSubmit={submit} noValidate><fieldset disabled={!editable || saving}><legend>بيانات السؤال</legend><label htmlFor="admin-categoryId">الفئة<select id="admin-categoryId" value={draft.categoryId} onChange={event => update('categoryId', event.target.value)} aria-invalid={Boolean(errors.categoryId)}><option value="">اختر فئة…</option>{categories.map(category => <option key={category.id} value={category.id}>{category.titleAr || category.id}</option>)}</select></label>{categoryState === 'loading' ? <p role="status">جارٍ تحميل الفئات المتاحة…</p> : categoryState === 'empty' ? <p className="admin-field-error">لا توجد بيانات فئات متاحة. أضف بيانات الفئة أو حدّث الصفحة قبل الحفظ.</p> : categoryState === 'error' ? <p className="admin-field-error">تعذر تحميل الفئات. حدّث الصفحة قبل الحفظ.</p> : null}{errors.categoryId ? <p className="admin-field-error">{errors.categoryId}</p> : null}<label htmlFor="admin-modality">النمط<select id="admin-modality" value={draft.modality} onChange={event => update('modality', event.target.value as Draft['modality'])}><option value="classic">تقليدي</option><option value="image">صورة</option><option value="charades">تمثيل</option></select></label><p className="admin-hint">{sourceHint}</p><label htmlFor="admin-headerAr">العنوان<input id="admin-headerAr" value={draft.headerAr} onChange={event => update('headerAr', event.target.value)} aria-invalid={Boolean(errors.headerAr)} placeholder="عنوان عربي موجز" /></label>{errors.headerAr ? <p className="admin-field-error">{errors.headerAr}</p> : null}<label htmlFor="admin-promptAr">نص السؤال<textarea id="admin-promptAr" value={draft.promptAr} onChange={event => update('promptAr', event.target.value)} aria-invalid={Boolean(errors.promptAr)} /></label>{errors.promptAr ? <p className="admin-field-error">{errors.promptAr}</p> : null}<label htmlFor="admin-canonicalAnswer">الإجابة المرجعية<input id="admin-canonicalAnswer" value={draft.canonicalAnswer} onChange={event => update('canonicalAnswer', event.target.value)} aria-invalid={Boolean(errors.canonicalAnswer)} /></label>{errors.canonicalAnswer ? <p className="admin-field-error">{errors.canonicalAnswer}</p> : null}<label htmlFor="admin-acceptedAnswers">الإجابات المقبولة، إجابة في كل سطر<textarea id="admin-acceptedAnswers" value={draft.acceptedAnswers} onChange={event => update('acceptedAnswers', event.target.value)} /></label></fieldset><fieldset disabled={!editable || saving}><legend>المصادر</legend><p className="admin-hint">أضف المصدر عند توفره. كل مصدر مضاف يحتاج رابط HTTPS والناشر والعنوان.</p>{draft.sources.map((source, index) => <div className="admin-source" key={index}><p className="admin-source__title">مصدر {index + 1}</p><label htmlFor={index === 0 ? 'admin-sourceUrl' : `admin-sourceUrl-${index}`}>{index === 0 ? 'رابط HTTPS' : `رابط HTTPS ${index + 1}`}<input id={index === 0 ? 'admin-sourceUrl' : `admin-sourceUrl-${index}`} type="url" dir="ltr" value={source.sourceUrl} onChange={event => { const sources = [...draft.sources]; sources[index] = { ...source, sourceUrl: event.target.value }; update('sources', sources); }} aria-invalid={Boolean(errors[`source-${index}`])} /></label><label>الناشر<input value={source.publisher} onChange={event => { const sources = [...draft.sources]; sources[index] = { ...source, publisher: event.target.value }; update('sources', sources); }} /></label><label>عنوان المصدر<input value={source.title} onChange={event => { const sources = [...draft.sources]; sources[index] = { ...source, title: event.target.value }; update('sources', sources); }} /></label><label>درجة المصدر<select value={source.sourceTier} onChange={event => { const sources = [...draft.sources]; sources[index] = { ...source, sourceTier: event.target.value }; update('sources', sources); }}><option value="primary">أولي</option><option value="secondary">ثانوي</option></select></label>{errors[`source-${index}`] ? <p className="admin-field-error">{errors[`source-${index}`]}</p> : null}{draft.sources.length > 1 ? <button className="text-link" type="button" onClick={() => update('sources', draft.sources.filter((_, itemIndex) => itemIndex !== index))}>حذف هذا المصدر</button> : null}</div>)}{draft.sources.length < 16 ? <button className="button button--secondary" type="button" onClick={() => update('sources', [...draft.sources, emptySource()])}>إضافة مصدر</button> : null}</fieldset><fieldset disabled={!editable || saving}><legend>جاهزية المراجعة</legend><label className="admin-check"><input checked={draft.ready} type="checkbox" onChange={event => update('ready', event.target.checked)} />تجهيز للمراجعة بعد الحفظ</label><p className="admin-hint">التحقق الأولي لا يعني الموافقة أو النشر.</p></fieldset><p aria-live="polite" className="admin-form-status">{status}</p>{admin?.dirty ? <p className="admin-hint">احفظ التعديلات أولاً قبل التحقق أو إرسال النسخة المحفوظة للمراجعة.</p> : null}{editable ? <div className="admin-inline-actions"><button className="button button--primary" type="submit" disabled={saving || categoryState !== 'ready'}>{operation === 'save' ? 'جارٍ الحفظ…' : !loadReady ? 'جارٍ تحميل السؤال…' : 'حفظ المسودة'}</button><button className="button button--secondary" type="button" disabled={!revision || saving || checking || admin?.dirty} onClick={() => void validateSaved()}>{checking ? 'جارٍ التحقق…' : 'تحقق'}</button><button className="button button--secondary" type="button" disabled={!revision || saving || submittingReview || !draft.ready || admin?.dirty} onClick={() => void submitForReview()}>{submittingReview ? 'جارٍ الإرسال…' : 'إرسال للمراجعة'}</button></div> : <p className="admin-notice">{admin?.session.mutationMode === 'staged' && capabilities(admin.session, 'questions.write') ? 'وضع التغيير مرحلي الآن؛ لا يمكن تعديل أو إرسال المسودات حتى يفتح الخادم التعديلات.' : 'هذه الجلسة للقراءة فقط؛ لا تملك صلاحية تعديل الأسئلة أو إرسالها للمراجعة.'}</p>}</form><p className="admin-notice">الموافقة النهائية والإيصالات الموقعة غير متاحتين من هذا السطح حتى تتوفر متطلبات الإصدار المختوم.</p></AdminSurface>;
}

export function AdminUsersRoute() {
  const adminSession = useAdmin(); const canWrite = capabilities(adminSession?.session ?? null, 'users.write') && adminSession?.session.mutationMode === 'enabled'; const [identifier, setIdentifier] = useState(''); const [user, setUser] = useState<Row | null>(null); const [notice, setNotice] = useState('ابحث بمعرّف Firebase UID الدقيق أو البريد الكامل.'); const [pending, setPending] = useState(false); const admin = user?.admin && typeof user.admin === 'object' ? user.admin as Row : null; const revision = Number(admin?.authzVersion ?? 0);
  const lookup = async () => { setNotice('جارٍ البحث…'); try { setUser(await lookupUser(identifier.trim())); setNotice('تم تحميل الحساب.'); } catch { setUser(null); setNotice('لم يوجد الحساب أو لا تملك صلاحية عرضه.'); } };
  const mutate = async (kind: 'roles' | 'status' | 'revoke', form?: HTMLFormElement) => { if (!user || !canWrite) return; setPending(true); setNotice('جارٍ تطبيق التغيير وتحديث المطالبات…'); try { if (kind === 'roles' && form) { const data = new FormData(form); const list = (name: string) => String(data.get(name) || '').split(',').map(value => value.trim()).filter(Boolean); await updateUserRole({ uid: user.uid, operationId: crypto.randomUUID(), expectedRevision: revision, roles: list('roles'), categoryScopes: list('categoryScopes'), reviewerScopes: list('reviewerScopes'), enabled: data.get('enabled') === 'on' }); } else if (kind === 'status') await setUserStatus({ uid: user.uid, operationId: crypto.randomUUID(), expectedRevision: revision, disabled: !user.disabled }); else await revokeUserSessions({ uid: user.uid, operationId: crypto.randomUUID(), expectedRevision: revision }); await lookup(); setNotice('سُجل التغيير في التدقيق. على العميل تجديد رمز الهوية قبل ظهور الصلاحية الجديدة.'); } catch { setNotice('رُفض التغيير أو فشلت مزامنة Firebase Auth؛ لم تفترض الواجهة نجاحاً.'); } finally { setPending(false); } };
  return <AdminSurface title="المستخدمون والصلاحيات" description="بحث دقيق فقط؛ لا توجد قائمة حسابات عامة."><div className="admin-toolbar"><label>UID أو البريد الدقيق<input dir="ltr" value={identifier} onChange={event => setIdentifier(event.target.value)} /></label><button className="button button--primary" type="button" onClick={() => void lookup()} disabled={!identifier.trim()}>بحث</button></div><p aria-live="polite">{notice}</p>{user ? <section className="admin-detail"><dl className="admin-inventory"><div><dt>المعرف</dt><dd dir="ltr">{String(user.uid)}</dd></div><div><dt>البريد</dt><dd dir="ltr">{text(user.email)}</dd></div><div><dt>الحالة</dt><dd>{user.disabled ? 'معطل' : 'نشط'}</dd></div></dl>{canWrite ? <form className="admin-form" onSubmit={event => { event.preventDefault(); void mutate('roles', event.currentTarget); }}><label>الأدوار، مفصولة بفاصلة<input name="roles" dir="ltr" defaultValue={Array.isArray(admin?.roles) ? admin.roles.join(',') : 'viewer'} /></label><label>نطاقات الفئات، مفصولة بفاصلة<input name="categoryScopes" dir="ltr" defaultValue={Array.isArray(admin?.categoryScopes) ? admin.categoryScopes.join(',') : ''} /></label><label>اختصاصات المراجع، مفصولة بفاصلة<input name="reviewerScopes" dir="ltr" defaultValue={Array.isArray(admin?.reviewerScopes) ? admin.reviewerScopes.join(',') : ''} /></label><p className="admin-hint">دور المراجع يحتاج نطاق فئات واختصاصاً واحداً على الأقل. الخادم يفرض النطاقات مستقلاً عن الواجهة.</p><label className="admin-check"><input name="enabled" type="checkbox" defaultChecked={admin?.enabled === true} />سجل إداري مفعل</label><div className="admin-inline-actions"><button className="button button--primary" disabled={pending} type="submit">حفظ الأدوار والنطاقات</button><button className="button button--secondary" disabled={pending} type="button" onClick={() => void mutate('revoke')}>إلغاء الجلسات</button><button className="button button--danger" disabled={pending} type="button" onClick={() => void mutate('status')}>{user.disabled ? 'إعادة تفعيل Auth' : 'تعطيل Auth'}</button></div></form> : <p className="admin-notice">{adminSession?.session.mutationMode === 'staged' ? 'وضع التغيير مرحلي الآن؛ يمكن عرض الحساب فقط حتى يفتح الخادم التعديلات.' : 'هذه الجلسة تستطيع عرض الحساب فقط، ولا تملك تغيير الأدوار أو الجلسات.'}</p>}</section> : null}</AdminSurface>;
}

export function AdminSettingsRoute() {
  const admin = useAdmin(); const canWrite = capabilities(admin?.session ?? null, 'settings.write') && admin?.session.mutationMode === 'enabled'; const [runtime, setRuntime] = useState<Row | null>(null); const [notice, setNotice] = useState('جارٍ تحميل الإعدادات الآمنة…'); const [pending, setPending] = useState(false);
  useEffect(() => { let live = true; void getSettings().then(value => { if (live) { setRuntime((value.runtime ?? {}) as Row); setNotice('الإعدادات محمّلة.'); } }).catch(() => live && setNotice('تعذر تحميل الإعدادات.')); return () => { live = false; }; }, []);
  if (!runtime) return <AdminSurface title="إعدادات وقت التشغيل" description="المفاتيح والأدوار وقواعد الأمان ليست إعدادات قابلة للتحرير."><p role="status">{notice}</p></AdminSurface>;
  return <AdminSurface title="إعدادات وقت التشغيل" description="قيم مرئية آمنة؛ لا تغيّر هذه الصفحة إعدادات اللعب ما لم يفتح الخادم وضع التغيير."><form className="admin-form" onSubmit={event => { event.preventDefault(); if (!canWrite) return; const data = new FormData(event.currentTarget); setPending(true); setNotice('جارٍ الحفظ…'); void updateSettings({ operationId: crypto.randomUUID(), expectedRevision: Number(runtime.revision ?? 0), settings: { maintenanceMode: data.get('maintenanceMode') === 'on', maintenanceMessageAr: String(data.get('maintenanceMessageAr') || ''), roomCreationEnabled: data.get('roomCreationEnabled') === 'on', defaultQuestionTimerSeconds: Number(data.get('defaultQuestionTimerSeconds')), defaultOpponentTimerSeconds: Number(data.get('defaultOpponentTimerSeconds')), roomRetentionDays: Number(data.get('roomRetentionDays')) } }).then(result => { setRuntime({ ...runtime, revision: result.revision }); setNotice('حُفظت الإعدادات الآمنة.'); }).catch(error => setNotice(String(error).includes('aborted') ? 'تعارض: حدّث الصفحة قبل إعادة الحفظ.' : 'تعذر حفظ الإعدادات؛ بقيت القيم المعروضة دون ادعاء نجاح.')).finally(() => setPending(false)); }}><fieldset disabled={!canWrite || pending}><label className="admin-check"><input name="maintenanceMode" type="checkbox" defaultChecked={runtime.maintenanceMode === true} />وضع الصيانة</label><label>رسالة الصيانة<textarea name="maintenanceMessageAr" defaultValue={String(runtime.maintenanceMessageAr ?? '')} /></label><label className="admin-check"><input name="roomCreationEnabled" type="checkbox" defaultChecked={runtime.roomCreationEnabled !== false} />السماح بإنشاء الغرف</label><label>مؤقت السؤال<input name="defaultQuestionTimerSeconds" type="number" min="5" max="600" defaultValue={Number(runtime.defaultQuestionTimerSeconds ?? 30)} /></label><label>مؤقت الخصم<input name="defaultOpponentTimerSeconds" type="number" min="3" max="300" defaultValue={Number(runtime.defaultOpponentTimerSeconds ?? 10)} /></label><label>احتفاظ ملخص الغرفة بالأيام<input name="roomRetentionDays" type="number" min="1" max="365" defaultValue={Number(runtime.roomRetentionDays ?? 30)} /></label></fieldset><p aria-live="polite">{notice}</p>{canWrite ? <button className="button button--primary" disabled={pending} type="submit">حفظ الإعدادات</button> : <p className="admin-notice">وضع التغيير مرحلي الآن؛ الإعدادات للقراءة فقط حتى يفتح الخادم التعديلات.</p>}</form></AdminSurface>;
}

function Status({ value, children }: { value: unknown; children?: ReactNode }) { return <span className={`admin-status admin-status--${String(value ?? 'unknown').toLowerCase()}`}>{children ?? labelStatus(value)}</span>; }
function Recovery({ message, retry }: { message: string; retry: () => void }) { return <div className="admin-notice" role="alert"><p>{message}</p><button className="button button--secondary" type="button" onClick={retry}>إعادة المحاولة</button></div>; }
function LoadingRows() { return <div className="admin-loading" role="status" aria-label="جارٍ تحميل البيانات"><span /><span /><span /><p>جارٍ تحميل البيانات من الخادم…</p></div>; }
function HealthSummary({ value }: { value: Row }) { const components = value.components && typeof value.components === 'object' ? value.components as Row : {}; return <dl className="admin-health"><div><dt>وضع التغيير</dt><dd>{labelStatus(value.mutationMode)}</dd></div><div><dt>الإصدار النشط</dt><dd>{text(value.activeReleaseId)}</dd></div><div><dt>عمليات فاشلة</dt><dd>{text(value.failedJobs)}</dd></div><div><dt>غرف قديمة</dt><dd>{text(value.staleRooms)}</dd></div>{Object.entries(components).map(([name, status]) => <div key={name}><dt>{({ auth: 'الهوية', functions: 'الدوال', firestore: 'قاعدة البيانات', storage: 'التخزين', appCheck: 'حماية التطبيق' } as Record<string, string>)[name] ?? name}</dt><dd><Status value={status} /></dd></div>)}</dl>; }
function AdminSurface({ title, description, children, hideDefaultHeader = false }: { title: string; description: string; children: ReactNode; hideDefaultHeader?: boolean }) { useEffect(() => { document.title = `${title} | الخلية`; }, [title]); return <section className="admin-surface">{hideDefaultHeader ? null : <><p className="eyebrow">إدارة الخلية</p><h1>{title}</h1><p className="admin-description">{description}</p></>}{children}</section>; }
export function AdminRootRedirect() { return <Navigate replace to="/admin/overview" />; }
export function LegacyQuestionRedirect() { const { questionId } = useParams(); return <Navigate replace to={`/admin/drafts/${encodeURIComponent(questionId ?? '')}`} />; }
